/* Original Grade 3 lessons. Three bounded examples per challenge support
   replay; 36 lessons deepen the year path rather than certify a curriculum.
   No imported artwork, external requests, accounts, or answer evaluation. */
const Y = (suffix, title, topicId, unit, conceptKey, standards, goal, prerequisite, workedExample, explainPrompt, reviewPrompt) => ({
  id: 'g3y-' + suffix, title, worldId: ['geometry', 'measurement', 'measuring'].includes(topicId) ? 'studio' : topicId === 'fractions' ? 'garden' : ['division', 'multiplication'].includes(topicId) ? 'workshop' : 'meadow',
  bandId: 'elementary', gradeIds: ['3'], topicId, unitId: `g3-unit-${unit}`, conceptKey, conceptId: conceptKey, standards, sourceIds: [], lessonId: null, minutes: 9, goal, skill: goal,
  teacherNotes: 'Model one example together. Let the learner build, explain, and revisit the idea with a different example. Success here is practice evidence, not a mastery label.',
  lessonPlan: { goal, prerequisite, workedExample, explainPrompt, reviewPrompt }
});
